require_once __DIR__.'/../includes/init.php';require_role('owner');require_once __DIR__.'/../includes/layout.php';$pdo=db();$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));$error='';$tx=0;$revenue=0.0;$gross=0.0;$pending=0.0;$unpaid=0.0;$active=0;$summary=[];$days=[];$staffExit=[];try{[$a,$b]=valid_date_range($from,$to);$s=$pdo->prepare("SELECT COUNT(*) AS cnt,COALESCE(SUM(biaya_total),0) AS gross,COALESCE(SUM(CASE WHEN status_pembayaran='lunas' THEN biaya_total ELSE 0 END),0) AS revenue,COALESCE(SUM(CASE WHEN status_pembayaran='menunggu_verifikasi' THEN biaya_total ELSE 0 END),0) AS pending,COALESCE(SUM(CASE WHEN status_pembayaran='belum_bayar' THEN biaya_total ELSE 0 END),0) AS unpaid FROM v_rekap_transaksi WHERE status='keluar' AND waktu_keluar BETWEEN ? AND ?");$s->execute([$a,$b]);$r=$s->fetch();$tx=(int)$r['cnt'];$gross=(float)$r['gross'];$revenue=(float)$r['revenue'];$pending=(float)$r['pending'];$unpaid=(float)$r['unpaid'];$s=$pdo->prepare("SELECT COUNT(*) FROM v_rekap_transaksi WHERE status='masuk'");$s->execute();$active=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT jenis_kendaraan,COUNT(*) AS jumlah,COALESCE(SUM(CASE WHEN status_pembayaran='lunas' THEN biaya_total ELSE 0 END),0) AS pendapatan,COALESCE(SUM(CASE WHEN status_pembayaran='menunggu_verifikasi' THEN biaya_total ELSE 0 END),0) AS menunggu FROM v_rekap_transaksi WHERE status='keluar' AND waktu_keluar BETWEEN ? AND ? GROUP BY jenis_kendaraan ORDER BY jenis_kendaraan");$s->execute([$a,$b]);$summary=$s->fetchAll();$s=$pdo->prepare("SELECT DATE(waktu_keluar) AS hari, SUM(CASE WHEN status_pembayaran='lunas' THEN biaya_total ELSE 0 END) AS pendapatan FROM v_rekap_transaksi WHERE status='keluar' AND waktu_keluar BETWEEN ? AND ? GROUP BY DATE(waktu_keluar) ORDER BY hari");$s->execute([$a,$b]);foreach($s->fetchAll() as $x)$days[$x['hari']]=(float)$x['pendapatan'];$s=$pdo->prepare("SELECT id_user_petugas_keluar AS id_user,nama_petugas_keluar AS nama,COUNT(*) AS jumlah,COALESCE(SUM(CASE WHEN status_pembayaran='lunas' THEN biaya_total ELSE 0 END),0) AS pendapatan,COALESCE(SUM(CASE WHEN status_pembayaran='menunggu_verifikasi' THEN biaya_total ELSE 0 END),0) AS menunggu FROM v_rekap_transaksi WHERE status='keluar' AND waktu_keluar BETWEEN ? AND ? AND id_user_petugas_keluar IS NOT NULL GROUP BY id_user_petugas_keluar,nama_petugas_keluar ORDER BY pendapatan DESC");$s->execute([$a,$b]);$staffExit=$s->fetchAll();}catch(Throwable $e){if($e instanceof InvalidArgumentException){$error=$e->getMessage();}else{error_log('[ParkirSTRD owner dashboard] '.$e->getMessage());$error='Laporan belum dapat diproses. Periksa konfigurasi database.';}}
$labels=[];$vals=[];if(!$error){$start=new DateTimeImmutable($from);$end=new DateTimeImmutable($to);$span=$start->diff($end)->days;$step=$span>30?7:1;for($d=$start;$d<=$end;$d=$d->modify('+'.$step.' days')){$key=$d->format('Y-m-d');$labels[]=$d->format('d M');if($step===7){$sum=0;for($i=0;$i<7;$i++)$sum+=$days[(new DateTimeImmutable($key))->modify('+'.$i.' days')->format('Y-m-d')]??0;$vals[]=$sum;}else{$vals[]=$days[$key]??0;}}}
$chart=['type'=>'line','legend'=>false,'data'=>['labels'=>$labels,'datasets'=>[['label'=>'Pendapatan','data'=>$vals,'borderColor'=>'#3978ef','backgroundColor'=>'rgba(57,120,239,.12)','fill'=>true,'tension'=>.35,'pointRadius'=>3]]]];render_header('Dashboard Owner','dashboard');?>
<div class="page-intro"><div><h2>Ringkasan pendapatan</h2><p>Tampilan laporan read-only. Owner tidak dapat mengubah transaksi atau data master.</p></div><a class="btn btn-primary" href="<?= h(url('owner/laporan.php?from='.rawurlencode($from).'&to='.rawurlencode($to))) ?>">Detail laporan →</a></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><form method="get" class="filter-row"><div class="field"><label>Tanggal mulai</label><input type="date" name="from" required value="<?= h($from) ?>"></div><div class="field"><label>Tanggal akhir</label><input type="date" name="to" required value="<?= h($to) ?>"></div><button class="btn btn-primary">Terapkan</button></form></section><div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-label">Pendapatan terverifikasi</span><span class="stat-icon green">Rp</span></div><div class="stat-value" style="font-size:22px"><?= h(rupiah($revenue)) ?></div><div class="stat-foot">Pembayaran berstatus lunas</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Nilai transaksi bruto</span><span class="stat-icon">Rp</span></div><div class="stat-value" style="font-size:22px"><?= h(rupiah($gross)) ?></div><div class="stat-foot">Termasuk pembayaran menunggu atau belum dibayar</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">QRIS menunggu verifikasi</span><span class="stat-icon orange">◷</span></div><div class="stat-value" style="font-size:22px"><?= h(rupiah($pending)) ?></div><div class="stat-foot">Belum dihitung sebagai pendapatan terverifikasi</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Transaksi selesai</span><span class="stat-icon">⇄</span></div><div class="stat-value"><?= number_format($tx) ?></div><div class="stat-foot">Dalam rentang tanggal</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Rata-rata transaksi</span><span class="stat-icon cyan">∅</span></div><div class="stat-value" style="font-size:21px"><?= h(rupiah($tx?$revenue/$tx:0)) ?></div><div class="stat-foot">Pendapatan / transaksi selesai</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Sedang parkir</span><span class="stat-icon orange">◷</span></div><div class="stat-value"><?= number_format($active) ?></div><div class="stat-foot">Snapshot saat dashboard dibuka</div></article></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Grafik pendapatan</h2><p><?= h(date('d M Y',strtotime($from))) ?> – <?= h(date('d M Y',strtotime($to))) ?></p></div></div><div class="chart-wrap"><canvas data-chart="<?= h(json_encode($chart,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)) ?>"></canvas></div></section><section class="panel"><div class="panel-heading"><div><h2>Pendapatan terverifikasi per jenis kendaraan</h2><p>Pembayaran menunggu verifikasi ditampilkan terpisah.</p></div></div><div class="panel-body"><?php foreach($summary as $r): ?><div style="padding:14px 0;border-bottom:1px solid #eff2f7"><div class="area-top"><strong><?= h(ucfirst($r['jenis_kendaraan'])) ?></strong><span class="muted"><?= (int)$r['jumlah'] ?> transaksi</span></div><div style="font:800 17px Manrope;margin-top:5px"><?= h(rupiah($r['pendapatan'])) ?></div><div class="muted">Menunggu verifikasi: <?= h(rupiah($r['menunggu'])) ?></div></div><?php endforeach;if(!$summary): ?><div class="empty-state">Belum ada transaksi selesai pada periode ini.</div><?php endif; ?></div></section></div><section class="panel"><div class="panel-heading"><div><h2>Akses laporan</h2><p>Semua data bersumber dari view database v_rekap_transaksi.</p></div><a class="btn btn-primary" href="<?= h(url('owner/laporan.php?from='.rawurlencode($from).'&to='.rawurlencode($to))) ?>">Buka laporan lengkap</a></div><div class="panel-body"><div class="detail-grid"><div class="detail-item"><small>Sumber laporan</small><strong>v_rekap_transaksi</strong></div><div class="detail-item"><small>Hak akses database</small><strong>SELECT saja</strong></div><div class="detail-item"><small>Ekspor</small><strong>CSV</strong></div></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Pendapatan berdasarkan petugas keluar</h2><p>Nilai transaksi dialokasikan sekali kepada petugas yang memproses kendaraan keluar.</p></div></div><div class="table-wrap"><table><thead><tr><th>Petugas</th><th>Transaksi keluar</th><th>Pendapatan terverifikasi</th><th>Menunggu verifikasi</th></tr></thead><tbody><?php foreach($staffExit as $staff): ?><tr><td><?= h($staff['nama']) ?> <span class="muted">#<?= (int)$staff['id_user'] ?></span></td><td><?= (int)$staff['jumlah'] ?></td><td class="td-main"><?= h(rupiah($staff['pendapatan'])) ?></td><td><?= h(rupiah($staff['menunggu'])) ?></td></tr><?php endforeach; if(!$staffExit): ?><tr><td colspan="4"><div class="empty-state">Belum ada rekap petugas untuk periode ini.</div></td></tr><?php endif; ?></tbody></table></div></section><?php render_footer(); ?>